import time
import numpy as np
import random
import math
from copy import deepcopy

class CVRPSolver:
    def __init__(self, coordinates: np.ndarray, distance_matrix: np.ndarray, demands: list, vehicle_capacity: int):
        """
        Initialize the CVRP solver.

        Args:
            coordinates: Numpy array of shape (n, 2) containing the (x, y) coordinates of each node, including the depot.
            distance_matrix: Numpy array of shape (n, n) containing pairwise distances between nodes.
            demands: List of integers representing the demand of each node (first node is typically the depot with zero demand).
            vehicle_capacity: Integer representing the maximum capacity of each vehicle.
        """
        self.coordinates = coordinates
        self.distance_matrix = distance_matrix
        self.demands = demands
        self.vehicle_capacity = vehicle_capacity
        self.n = len(coordinates)

    # --- helper functions implementing the coevolutionary bandit hypergraph metaheuristic ---
    def _route_cost(self, route):
        # route: list of nodes excluding depot endpoints (e.g., [1,4,3])
        if len(route) == 0:
            return 0.0
        cost = self.distance_matrix[0, route[0]]
        for i in range(len(route) - 1):
            cost += self.distance_matrix[route[i], route[i+1]]
        cost += self.distance_matrix[route[-1], 0]
        return cost

    def _solution_cost(self, solution_routes):
        # sum costs of routes
        return sum(self._route_cost(r) for r in solution_routes)

    def _is_feasible(self, solution_routes):
        for r in solution_routes:
            if sum(self.demands[i] for i in r) > self.vehicle_capacity:
                return False
        # check coverage
        visited = set()
        for r in solution_routes:
            visited.update(r)
        # exclude depot 0
        required = set(range(1, self.n))
        return visited == required

    def _repair_capacity(self, routes):
        # Ensure no route exceeds capacity. If it does, split greedily.
        new_routes = []
        for r in routes:
            if len(r) == 0:
                continue
            cur_route = []
            cur_load = 0
            for node in r:
                demand = self.demands[node]
                if cur_load + demand > self.vehicle_capacity:
                    if cur_route:
                        new_routes.append(cur_route)
                    cur_route = [node]
                    cur_load = demand
                    # If single node demand > capacity, we still place it (infeasible but will be penalized)
                else:
                    cur_route.append(node)
                    cur_load += demand
            if cur_route:
                new_routes.append(cur_route)
        # Ensure every customer present; if some missing, add them greedily
        present = set().union(*([set(r) for r in new_routes] if new_routes else []))
        missing = [i for i in range(1, self.n) if i not in present]
        for m in missing:
            placed = False
            # try to append to any route that can take it
            for r in new_routes:
                if sum(self.demands[x] for x in r) + self.demands[m] <= self.vehicle_capacity:
                    r.append(m)
                    placed = True
                    break
            if not placed:
                new_routes.append([m])
        return new_routes

    def _flatten_solution(self, routes):
        # convert list of routes to flat list with zeros delimiting routes
        flat = []
        for r in routes:
            flat.append(0)
            flat.extend(r)
        flat.append(0)
        # remove consecutive duplicate zeros (if any) except maintain route separators
        # ensure starts with 0 and ends with 0
        if flat[0] != 0:
            flat.insert(0, 0)
        if flat[-1] != 0:
            flat.append(0)
        return flat

    def _decode_flat(self, flat):
        # convert flat list with zeros into list of routes (exclude depot endpoints)
        routes = []
        cur = []
        for node in flat:
            if node == 0:
                if cur:
                    routes.append(cur)
                    cur = []
            else:
                cur.append(node)
        if cur:
            routes.append(cur)
        return routes

    def _init_islands(self, island_count, seed=None):
        rng = np.random.RandomState(seed)
        base_ops = ['crossover', 'merge', 'split', '2opt', 'relocate']
        islands = []
        for i in range(island_count):
            ops = deepcopy(base_ops)
            rng.shuffle(ops)
            focus = 'feasibility' if (i % 2 == 0) else 'cost'
            islands.append({
                'operator_portfolio': ops,
                'focus_profile': focus,
            })
        return islands

    def _init_population(self, islands, per_island_pop=8):
        # create simple greedy and randomized greedy solutions per island
        populations = []
        all_customers = list(range(1, self.n))
        for isl in islands:
            pop = []
            for p in range(per_island_pop):
                # randomized greedy: shuffle and pack according to capacity
                order = all_customers.copy()
                random.shuffle(order)
                routes = []
                cur = []
                cur_load = 0
                for node in order:
                    d = self.demands[node]
                    if cur_load + d > self.vehicle_capacity:
                        if cur:
                            routes.append(cur)
                        cur = [node]
                        cur_load = d
                    else:
                        cur.append(node)
                        cur_load += d
                if cur:
                    routes.append(cur)
                # local quick improvement: sort nodes in route by nearest neighbor heuristic
                for idx, r in enumerate(routes):
                    if len(r) <= 2:
                        continue
                    seq = [r[0]]
                    remaining = set(r[1:])
                    while remaining:
                        last = seq[-1]
                        next_node = min(remaining, key=lambda x: self.distance_matrix[last, x])
                        seq.append(next_node)
                        remaining.remove(next_node)
                    routes[idx] = seq
                routes = self._repair_capacity(routes)
                pop.append(routes)
            populations.append(pop)
        return populations

    def _init_bandits(self, islands):
        bandits = []
        for isl in islands:
            ops = isl['operator_portfolio']
            bandit = {op: {'value': 1.0, 'count': 0} for op in ops}
            bandits.append(bandit)
        return bandits

    def _select_parents(self, population, focus_profile):
        # tournament selection: prefer feasible and low cost depending on focus_profile
        k = min(3, len(population))
        candidates = random.sample(population, k)
        def score(sol):
            cost = self._solution_cost(sol)
            feasible = self._is_feasible(sol)
            if focus_profile == 'feasibility':
                return (0 if feasible else 1, cost)
            else:
                return (0 if feasible else 1, cost)
        parents = sorted(candidates, key=lambda s: score(s))[:2]
        return parents

    def _bandit_select(self, bandit, budget=1, eps=0.1):
        # simple epsilon-greedy: with prob eps choose random, else choose highest estimated value
        ops = list(bandit.keys())
        if random.random() < eps:
            chosen = random.choice(ops)
            return {'recombination': chosen, 'local_search': chosen}
        # choose by highest value (could tie)
        best = max(ops, key=lambda o: bandit[o]['value'])
        return {'recombination': best, 'local_search': best}

    def _ordered_crossover(self, p1, p2):
        # Flatten parents and perform ordered crossover on customer sequence.
        seq1 = [node for r in p1 for node in r]
        seq2 = [node for r in p2 for node in r]
        if not seq1 or not seq2:
            base = seq1 + seq2
            order = list(dict.fromkeys(base))
            # split greedily
            routes = []
            cur = []; cur_load=0
            for node in order:
                d = self.demands[node]
                if cur_load + d > self.vehicle_capacity:
                    if cur: routes.append(cur)
                    cur=[node]; cur_load=d
                else:
                    cur.append(node); cur_load+=d
            if cur: routes.append(cur)
            return routes
        a, b = sorted(random.sample(range(len(seq1)), 2))
        cut = seq1[a:b+1]
        child_seq = []
        leftover = [x for x in seq2 if x not in cut]
        child_seq = leftover[:a] + cut + leftover[a:]
        # ensure all customers present
        seen = set(child_seq)
        for node in range(1, self.n):
            if node not in seen:
                child_seq.append(node)
        # split into routes greedily
        routes = []
        cur = []; cur_load = 0
        for node in child_seq:
            d = self.demands[node]
            if cur_load + d > self.vehicle_capacity:
                if cur:
                    routes.append(cur)
                cur = [node]; cur_load = d
            else:
                cur.append(node); cur_load += d
        if cur: routes.append(cur)
        return routes

    def _merge_recombination(self, p1, p2):
        # merge routes that appear in both parents; otherwise take best of both by route cost
        routes = []
        all_routes = p1 + p2
        used = set()
        for r in all_routes:
            tup = tuple(r)
            if tup in used:
                continue
            # try to add r if capacity allows
            if sum(self.demands[x] for x in r) <= self.vehicle_capacity:
                routes.append(r.copy())
                used.add(tup)
        # add any missing customers
        present = set().union(*([set(r) for r in routes] if routes else []))
        for node in range(1, self.n):
            if node not in present:
                # append to route with most spare capacity or create new
                best_idx = None
                best_spare = -1
                for i, r in enumerate(routes):
                    spare = self.vehicle_capacity - sum(self.demands[x] for x in r)
                    if self.demands[node] <= spare and spare > best_spare:
                        best_spare = spare
                        best_idx = i
                if best_idx is not None:
                    routes[best_idx].append(node)
                else:
                    routes.append([node])
        return routes

    def _split_recombination(self, parents):
        # take a route from a random parent and split it/randomize
        p = random.choice(parents)
        if not p:
            # fallback to random greedy
            nodes = list(range(1, self.n))
            random.shuffle(nodes)
            routes = []
            cur = []; cur_load=0
            for node in nodes:
                d = self.demands[node]
                if cur_load + d > self.vehicle_capacity:
                    routes.append(cur)
                    cur=[node]; cur_load=d
                else:
                    cur.append(node); cur_load+=d
            if cur: routes.append(cur)
            return routes
        r = random.choice(p)
        # split r into two parts
        if len(r) <= 1:
            return self._merge_recombination(p, p)
        cut = random.randint(1, len(r)-1)
        part1 = r[:cut]; part2 = r[cut:]
        other_nodes = [x for p_ in parents for rr in p_ for x in rr if x not in part1 and x not in part2]
        # build routes
        routes = [part1, part2]
        # attach others greedily
        for node in other_nodes:
            placed = False
            for idx in range(len(routes)):
                if sum(self.demands[x] for x in routes[idx]) + self.demands[node] <= self.vehicle_capacity:
                    routes[idx].append(node)
                    placed = True
                    break
            if not placed:
                routes.append([node])
        return routes

    def _recombine_hypergraph(self, parents, op_name):
        # high-level recombination that tries to preserve shared substructures (approximation)
        if op_name == 'crossover':
            return self._ordered_crossover(parents[0], parents[1])
        elif op_name == 'merge':
            return self._merge_recombination(parents[0], parents[1])
        elif op_name == 'split':
            return self._split_recombination(parents)
        else:
            # default: crossover
            return self._ordered_crossover(parents[0], parents[1])

    def _local_search_2opt(self, routes, time_budget_ms=20):
        # apply simple 2-opt within each route
        end = time.time() + (time_budget_ms / 1000.0)
        for idx, r in enumerate(routes):
            improved = True
            while improved and time.time() < end:
                improved = False
                L = len(r)
                if L < 3:
                    break
                for i in range(L - 2):
                    for j in range(i + 2, L):
                        if j - i == 1:
                            continue
                        a, b = r[i], r[i+1]
                        c, d = r[j], r[(j+1) % L] if (j+1) < L else None
                        # compute delta
                        if d is None:
                            before = self.distance_matrix[a, b] + self.distance_matrix[c, 0]
                            after = self.distance_matrix[a, c] + self.distance_matrix[b, 0]
                        else:
                            before = self.distance_matrix[a, b] + self.distance_matrix[c, d]
                            after = self.distance_matrix[a, c] + self.distance_matrix[b, d]
                        if after + 1e-9 < before:
                            # perform 2-opt
                            newr = r[:i+1] + list(reversed(r[i+1:j+1])) + (r[j+1:] if j+1 < L else [])
                            routes[idx] = newr
                            r = newr
                            improved = True
                            break
                    if improved or time.time() >= end:
                        break
        return routes

    def _local_search_relocate(self, routes, time_budget_ms=20):
        # move single customers between routes to improve cost while respecting capacity
        end = time.time() + (time_budget_ms / 1000.0)
        routes = deepcopy(routes)
        improved = True
        while improved and time.time() < end:
            improved = False
            for i in range(len(routes)):
                r = routes[i]
                for j_idx in range(len(r)):
                    node = r[j_idx]
                    best_gain = 0
                    best_place = None
                    cur_cost = self._route_cost(r)
                    # try moving node to other route positions
                    for k in range(len(routes)):
                        if k == i:
                            continue
                        if sum(self.demands[x] for x in routes[k]) + self.demands[node] > self.vehicle_capacity:
                            continue
                        for pos in range(len(routes[k]) + 1):
                            # create candidate
                            new_r_i = r[:j_idx] + r[j_idx+1:]
                            new_r_k = routes[k][:pos] + [node] + routes[k][pos:]
                            gain = (self._route_cost(new_r_i) + self._route_cost(new_r_k)) - (self._route_cost(r) + self._route_cost(routes[k]))
                            if gain < best_gain - 1e-9:
                                best_gain = gain
                                best_place = (k, pos, new_r_i, new_r_k)
                    if best_place:
                        k, pos, new_ri, new_rk = best_place
                        routes[i] = new_ri
                        routes[k] = new_rk
                        improved = True
                        break
                if improved or time.time() >= end:
                    break
        # remove empty routes
        routes = [r for r in routes if r]
        return routes

    def _constraint_propagate_and_repair(self, routes):
        routes = self._repair_capacity(routes)
        # if duplicate nodes occur (shouldn't), fix
        seen = set()
        clean_routes = []
        for r in routes:
            newr = []
            for node in r:
                if node not in seen:
                    newr.append(node)
                    seen.add(node)
            if newr:
                clean_routes.append(newr)
        # add missing nodes
        missing = [i for i in range(1, self.n) if i not in seen]
        for m in missing:
            placed = False
            for r in clean_routes:
                if sum(self.demands[x] for x in r) + self.demands[m] <= self.vehicle_capacity:
                    r.append(m)
                    placed = True
                    break
            if not placed:
                clean_routes.append([m])
        return clean_routes

    def _evaluate(self, routes):
        cost = self._solution_cost(routes)
        feasible = self._is_feasible(routes)
        # Penalize infeasibility heavily proportional to overload
        overload = 0
        for r in routes:
            overload += max(0, sum(self.demands[i] for i in r) - self.vehicle_capacity)
        penalized_cost = cost + 1000.0 * overload + (0 if feasible else 500.0)
        return {'cost': cost, 'feasible': feasible, 'penalized': penalized_cost}

    def _archive_update(self, archive, candidate, evaluation):
        # archive holds best feasible solution (min cost)
        if evaluation['feasible']:
            if archive['best'] is None or evaluation['cost'] < archive['best_cost']:
                archive['best'] = deepcopy(candidate)
                archive['best_cost'] = evaluation['cost']
        # always store best penalized for selection diversity
        if archive['best_penalized'] is None or evaluation['penalized'] < archive['best_penalized_cost']:
            archive['best_penalized'] = deepcopy(candidate)
            archive['best_penalized_cost'] = evaluation['penalized']

    def _bandit_reward_function(self, old_eval, new_eval):
        # reward positive if penalized cost decreased or feasibility improved
        reward = old_eval['penalized'] - new_eval['penalized']
        # extra bonus if infeasible -> feasible
        if (not old_eval['feasible']) and new_eval['feasible']:
            reward += 1000.0
        return reward

    def _bandit_update(self, bandit, op_name, reward):
        entry = bandit.get(op_name)
        if entry is None:
            # add new op
            bandit[op_name] = {'value': 1.0, 'count': 0}
            entry = bandit[op_name]
        entry['count'] += 1
        # incremental update of estimated value (simple learning rate)
        lr = 1.0 / max(5, entry['count'])
        entry['value'] = (1 - lr) * entry['value'] + lr * reward

    def _migrate(self, populations, islands, policy='random'):
        # simple migration: swap a random individual between random island pairs
        island_count = len(populations)
        if island_count < 2:
            return populations
        a, b = random.sample(range(island_count), 2)
        if not populations[a] or not populations[b]:
            return populations
        ia = random.randrange(len(populations[a]))
        ib = random.randrange(len(populations[b]))
        populations[a][ia], populations[b][ib] = populations[b][ib], populations[a][ia]
        return populations

    def _adapt_operator_pools(self, islands, bandits, archive, adapt_rate=0.1):
        # occasionally replace the worst operator in an island with a copy of the best global operator
        # identify global best operator by average bandit value
        global_vals = {}
        for b in bandits:
            for op, entry in b.items():
                global_vals.setdefault(op, []).append(entry['value'])
        avg_vals = {op: (sum(vs)/len(vs)) for op, vs in global_vals.items()}
        if not avg_vals:
            return
        best_op = max(avg_vals.items(), key=lambda x: x[1])[0]
        for i, isl in enumerate(islands):
            if random.random() < adapt_rate:
                local_ops = isl['operator_portfolio']
                # replace worst local operator with best_op
                if local_ops:
                    # compute local values
                    local_vals = [(op, bandits[i].get(op, {'value':0})['value']) for op in local_ops]
                    worst_op = min(local_vals, key=lambda x: x[1])[0]
                    if worst_op != best_op:
                        # replace
                        isl['operator_portfolio'] = [best_op if o == worst_op else o for o in local_ops]
                        # ensure bandit entry exists
                        if best_op not in bandits[i]:
                            bandits[i][best_op] = {'value': 1.0, 'count': 0}

    # --- main solve method implementing the pseudocode loop ---
    def solve(self) -> list:
        """
        Solve the Capacitated Vehicle Routing Problem (CVRP).

        Returns:
            A one-dimensional list of integers representing the sequence of nodes visited by all vehicles.
        """
        # parameters (tunable)
        island_count = min(4, max(1, self.n // 5))
        per_island_pop = 8
        operator_budget = 1
        parallelism = min(2, island_count)
        migration_interval = 2.0  # seconds
        adapt_rate = 0.12
        time_limit = max(1.0, min(30.0, 0.1 * self.n))  # auto time limit based on instance size

        # init
        seed = int(time.time()) % (2**31 - 1)
        islands = self._init_islands(island_count, seed=seed)
        populations = self._init_population(islands, per_island_pop=per_island_pop)
        archive = {'best': None, 'best_cost': float('inf'), 'best_penalized': None, 'best_penalized_cost': float('inf')}
        bandits = self._init_bandits(islands)

        start = time.time()
        last_migration = start

        # Precompute evaluations for population to speed selection
        pop_evals = []
        for isl_pop in populations:
            evals = [self._evaluate(ind) for ind in isl_pop]
            pop_evals.append(evals)

        # main loop
        while time.time() - start < time_limit:
            # sample islands to operate on
            island_indices = random.sample(range(len(islands)), k=min(parallelism, len(islands)))
            for idx in island_indices:
                island = islands[idx]
                population = populations[idx]
                if not population:
                    continue
                # select parents
                parents = self._select_parents(population, island['focus_profile'])
                # bandit select operators
                ops = self._bandit_select(bandits[idx], budget=operator_budget)
                recomb_op = ops['recombination']
                local_op = ops['local_search']
                # recombine
                offspring = self._recombine_hypergraph(parents, recomb_op)
                # repair
                offspring = self._constraint_propagate_and_repair(offspring)
                # local search
                if local_op == '2opt':
                    offspring = self._local_search_2opt(offspring, time_budget_ms=20)
                elif local_op == 'relocate':
                    offspring = self._local_search_relocate(offspring, time_budget_ms=20)
                else:
                    # minor improvement by 2opt as default
                    offspring = self._local_search_2opt(offspring, time_budget_ms=10)
                # evaluate
                new_eval = self._evaluate(offspring)
                # update archive
                self._archive_update(archive, offspring, new_eval)
                # compute baseline old evaluation: use best penalized in island population as baseline
                # pick parent[0] evaluation if available
                old_eval = self._evaluate(parents[0])
                # reward
                reward = self._bandit_reward_function(old_eval, new_eval)
                # update bandit
                self._bandit_update(bandits[idx], recomb_op, reward)
                # insert offspring into population (replace worst)
                # find worst index by penalized cost
                worst_idx = max(range(len(population)), key=lambda i: self._evaluate(population[i])['penalized'])
                populations[idx][worst_idx] = offspring
                # update pop_evals for this island
                pop_evals[idx] = [self._evaluate(ind) for ind in populations[idx]]

            # migration
            now = time.time()
            if now - last_migration > migration_interval:
                populations = self._migrate(populations, islands)
                last_migration = now

            # adapt operator pools
            self._adapt_operator_pools(islands, bandits, archive, adapt_rate=adapt_rate)

        # decode best solution from archive
        best_routes = archive['best']
        if best_routes is None:
            # fallback to best penalized
            best_routes = archive['best_penalized'] if archive['best_penalized'] is not None else self._init_population(islands, per_island_pop=1)[0]

        flat = self._flatten_solution(best_routes)
        # ensure requirements: start and end at depot, visits all customers exactly once
        # final sanity check/fix
        routes = self._decode_flat(flat)
        routes = self._constraint_propagate_and_repair(routes)
        final_flat = self._flatten_solution(routes)
        return final_flat

